                        in_arg = 1;
                        switch (in[1]) {
                        case ' ':
                        case '\\':
                                tosend = in[1];
                                in++;
                                break;

                        case 't':
                                tosend = '\t';
                                in++;
                                break;

                        case 'n':
                                tosend = '\n';
                                in++;
                                break;

                        case 'r':
                                tosend = '\r';
                                in++;
                                break;

                        case '#':
                                /* escaping of "#" only if comments are supported */
                                if (opts & PARSE_OPT_SHARP)
